// @generated by auto-design from design.config.ts. The Hello Kitty motion profile (expressive).
// Use with Motion (import { motion } from "motion/react") or element.animate(). Durations are in seconds.

export const duration = { fast: 0.15, base: 0.22, slow: 0.32, reveal: 1 } as const;

export const ease = { out: [0.16, 1, 0.3, 1], inOut: [0.87, 0, 0.13, 1] } as const;

/** The same curves as CSS strings, for element.animate() and inline styles. */
export const css = {
  easeOut: "cubic-bezier(0.16, 1, 0.3, 1)",
  easeInOut: "cubic-bezier(0.87, 0, 0.13, 1)",
  spring: "linear(0, 0.028, 0.098, 0.196, 0.308, 0.424, 0.538, 0.643, 0.738, 0.819, 0.887, 0.941, 0.983, 1.014, 1.036, 1.049, 1.057, 1.059, 1.057, 1.053, 1.047, 1.041, 1.034, 1.027, 1.021, 1.016, 1.011, 1.007, 1.004, 1.001, 0.999, 0.998, 0.997, 0.997, 0.997, 0.997, 1)",
} as const;

/** For drag, layout changes and anything that follows the pointer. */
export const spring = { type: "spring", duration: 0.35, bounce: 0.15 } as const;

/** Entering elements: a fade from scale 0.95 with 8px of travel. Never from scale 0. */
export const enter = {
  initial: { opacity: 0, scale: 0.95, y: 8 },
  animate: { opacity: 1, scale: 1, y: 0 },
  transition: { duration: duration.base, ease: ease.out },
} as const;

export const exit = {
  opacity: 0, scale: 0.95,
  transition: { duration: duration.fast, ease: ease.inOut },
} as const;

/** Content arriving as it scrolls into view: data, sections, text. Never a response to a press. */
export const reveal = {
  initial: { opacity: 0, y: 16 },
  whileInView: { opacity: 1, y: 0 },
  viewport: { once: true, amount: 0.4 },
  transition: { duration: duration.reveal, ease: ease.out },
} as const;

/** Seconds between items in a staggered reveal. */
export const stagger = 0.07;

/** Brand animation timing (launch films, social posts): slower and larger than product UI. */
export const brand = { beat: 0.82, stagger: 0.15, hold: 1.2, travel: 4.5 } as const;

/** Whether loops (spinners aside) may move at all. */
export const ambient = true;
